# KISS: direct, exhaustive, traceable. Two channels, two methods.
class Notifier:
    def __init__(self, email_client, sms_client):
        self.email_client = email_client
        self.sms_client = sms_client

    def send(self, user, msg: str) -> None:
        if user.channel == "email":
            self.email_client.send(user.email, msg)
        elif user.channel == "sms":
            self.sms_client.send(user.phone, msg)
        else:
            raise ValueError(f"unknown channel: {user.channel}")

