// KISS: one place, explicit rules. Extract when rules diverge.
class Pricing {
    double total(Order o) {
        double t = o.subtotal();
        if (o.coupon() != null) t -= o.coupon().discount(t);
        if (o.isMember()) t *= 0.95;
        return Math.max(t, 0);
    }
}
